// ID-Indizes für die Ergänzung älterer Einträge und Tagebuch-Snapshots.
const FOOD_CATALOG_BY_ID = new Map(FOOD_CATALOG.map(entry => [entry.id, entry]));
const RECIPE_CATALOG_BY_ID = new Map(RECIPE_CATALOG.map(entry => [entry.id, entry]));
function catalogSugarFor(id){
  const food = FOOD_CATALOG_BY_ID.get(id);
  if(food) return food.sugar ?? null;
  const recipeId = String(id ?? '').replace(/^recipe-food-/, '');
  const recipe = RECIPE_CATALOG_BY_ID.get(recipeId);
  if(!recipe) return null;
  const first = recipe.items?.[0]?.snapshot;
  return first?.sugar ?? recipe.sugar ?? null;
}
